import React, { useState } from 'react';
import { useDonors } from '../../contexts/DonorContext';

const DonorForm = () => {
    const [formData, setFormData] = useState({
        firstName: '',
        lastName: '',
        whatsappNumber: '',
        price: '',
        type: 'sheep' // Default to sheep
    });

    const [formError, setFormError] = useState('');
    const [formSuccess, setFormSuccess] = useState('');
    const { addDonor } = useDonors();

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const validateForm = () => {
        if (!formData.firstName.trim()) return "First name is required";
        if (!formData.lastName.trim()) return "Last name is required";
        if (!formData.whatsappNumber.trim()) return "WhatsApp number is required";
        if (!/^\+?\d{10,15}$/.test(formData.whatsappNumber.replace(/\s/g, ''))) {
            return "Please enter a valid WhatsApp number";
        }
        if (!formData.price || isNaN(formData.price) || Number(formData.price) <= 0) {
            return "Please enter a valid price";
        }
        return null;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setFormError('');
        setFormSuccess('');

        const error = validateForm();
        if (error) {
            setFormError(error);
            return;
        }

        try {
            const newDonor = await addDonor({
                ...formData,
                price: Number(formData.price)
            });

            setFormSuccess(`Donor ${formData.firstName} ${formData.lastName} registered successfully!`);
            setFormData({
                firstName: '',
                lastName: '',
                whatsappNumber: '',
                price: '',
                type: 'sheep'
            });
        } catch (error) {
            setFormError(`Failed to register donor: ${error.message}`);
            console.error(error);
        }
    };

    return (
        <div className="card max-w-2xl mx-auto">
            <h2 className="text-2xl font-bold text-center mb-6">Register New Donor</h2>

            {formError && (
                <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6">
                    <p className="text-red-700">{formError}</p>
                </div>
            )}

            {formSuccess && (
                <div className="bg-green-50 border-l-4 border-green-500 p-4 mb-6">
                    <p className="text-green-700">{formSuccess}</p>
                </div>
            )}

            <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label htmlFor="firstName" className="block text-sm font-medium text-gray-700 mb-1">
                            First Name
                        </label>
                        <input
                            type="text"
                            id="firstName"
                            name="firstName"
                            value={formData.firstName}
                            onChange={handleChange}
                            className="form-input"
                            placeholder="Enter first name"
                        />
                    </div>

                    <div>
                        <label htmlFor="lastName" className="block text-sm font-medium text-gray-700 mb-1">
                            Last Name
                        </label>
                        <input
                            type="text"
                            id="lastName"
                            name="lastName"
                            value={formData.lastName}
                            onChange={handleChange}
                            className="form-input"
                            placeholder="Enter last name"
                        />
                    </div>

                    <div>
                        <label htmlFor="whatsappNumber" className="block text-sm font-medium text-gray-700 mb-1">
                            WhatsApp Number
                        </label>
                        <input
                            type="text"
                            id="whatsappNumber"
                            name="whatsappNumber"
                            value={formData.whatsappNumber}
                            onChange={handleChange}
                            className="form-input"
                            placeholder="+213 XXXXXXXXX"
                        />
                    </div>

                    <div>
                        <label htmlFor="price" className="block text-sm font-medium text-gray-700 mb-1">
                            Donation Amount
                        </label>
                        <input
                            type="number"
                            id="price"
                            name="price"
                            value={formData.price}
                            onChange={handleChange}
                            className="form-input"
                            placeholder="Enter amount"
                            min="0"
                            step="0.01"
                        />
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Sacrifice Type
                        </label>
                        <div className="flex space-x-4 mt-1">
                            <label className="inline-flex items-center">
                                <input
                                    type="radio"
                                    name="type"
                                    value="sheep"
                                    checked={formData.type === 'sheep'}
                                    onChange={handleChange}
                                    className="form-radio h-5 w-5 text-green-600"
                                />
                                <span className="ml-2">Sheep</span>
                            </label>

                            <label className="inline-flex items-center">
                                <input
                                    type="radio"
                                    name="type"
                                    value="cow"
                                    checked={formData.type === 'cow'}
                                    onChange={handleChange}
                                    className="form-radio h-5 w-5 text-green-600"
                                />
                                <span className="ml-2">Cow (1/7 share)</span>
                            </label>
                        </div>
                    </div>
                </div>

                <div className="mt-8">
                    <button type="submit" className="btn btn-primary w-full">
                        Register Donor
                    </button>
                </div>
            </form>
        </div>
    );
};

export default DonorForm;
